const runFacetValuesSQL = `-- One row per (field, value): status, db_kind, trigger, provider profile, author.
SELECT field, value, count(*)::int AS count FROM (
  SELECT 'status' AS field, status AS value FROM runs WHERE tenant_id = $1 AND deleted_at IS NULL
  UNION ALL SELECT 'kind', summary->>'db_kind' FROM runs WHERE tenant_id = $1 AND deleted_at IS NULL AND summary ? 'db_kind'
  UNION ALL SELECT 'trigger', trigger FROM runs WHERE tenant_id = $1 AND deleted_at IS NULL
  UNION ALL SELECT 'provider_profile', summary->'provider_profile'->>'id' FROM runs WHERE tenant_id = $1 AND deleted_at IS NULL AND summary ? 'provider_profile'
  UNION ALL SELECT 'author', author_id::text FROM runs WHERE tenant_id = $1 AND deleted_at IS NULL AND author_id IS NOT NULL
) f GROUP BY field, value ORDER BY field, count DESC, value;`

type RunFacetValuesRow struct {
	Field string
	Value string
	Count int32
}

func (q *Queries) RunFacetValues(ctx context.Context, tenantID uuid.UUID) ([]RunFacetValuesRow, error) {
	rows, err := q.db.Query(ctx, runFacetValuesSQL, tenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RunFacetValuesRow
	for rows.Next() {
		var i RunFacetValuesRow
		if err := rows.Scan(&i.Field, &i.Value, &i.Count); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

